from sqlalchemy import (
    Column,
    Integer,
    String,
    DateTime,
    UniqueConstraint,
    func,
)

from app.core.database import Base

class IdempotencyKey(Base):
    __tablename__ = "idempotency_keys"

    id = Column(Integer, primary_key=True)

    # The user who performed the operation
    user_id = Column(Integer, nullable=False)

    # Allows the same key value to be used for different operations
    # e.g. create_property vs create_booking
    operation = Column(String(100), nullable=False)

    # UUID generated by the frontend
    key = Column(String(255), nullable=False)

    # Hash of the request body/input
    request_hash = Column(String(64), nullable=False)

    # ID of the resource created by this operation
    resource_id = Column(Integer, nullable=False)

    created_at = Column(
        DateTime,
        server_default=func.now(),
        nullable=False,
    )

    __table_args__ = (
        UniqueConstraint(
            "user_id",
            "operation",
            "key",
            name="uq_idem_user_op_key",
        ),
    )